package com.autocare.platform.order;
import com.autocare.platform.gateway.identity.*;
import com.autocare.platform.common.write.WriteIntegrityService;
import com.autocare.platform.common.write.WriteIntegrityService.*;
import com.fasterxml.jackson.databind.JsonNode;
import java.math.BigDecimal;
import java.util.*;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;
import static com.autocare.platform.order.ReservationStore.*;

/** Immutable, explicitly confirmed ranges for exact current quotation evidence. No repricing; comparison reads use the same source verifier. */
public class PricePolicies {
 static final String PATH="/api/admin/price-monitor/policies",RULE="R8B_PRICE_SOURCE_V1";
 private final ReservationStore db;private final OperatorIdentity operators;
 public PricePolicies(ReservationStore db,OperatorIdentity operators){this.db=db;this.operators=operators;}
 private void auth(OperatorActor a,boolean lock){operators.authorize(a,OperatorIdentity.Permission.PRICE_MONITOR,lock);}
 private void pageNumber(int p){if(p<1||p>1000000)throw ReservationInput.bad();}
 private ResponseStatusException conflict(){return new ResponseStatusException(HttpStatus.CONFLICT,"报价来源、依据版本或生效时间已变化，请重新读取");}
 static final String FROM=" FROM merchant_project q JOIN merchant m ON m.id=q.merchant_id JOIN standard_project p ON p.id=q.project_id WHERE q.is_deleted=0 AND q.on_shelf=1 AND m.status=1 AND m.is_deleted=0 AND p.status=1 AND p.is_deleted=0";
 private Map<String,Object> quote(long id,boolean lock){return db.one("SELECT q.id,q.merchant_id,q.project_id,q.price,q.on_shelf,m.name AS merchant_name,m.region_code,p.project_name,p.service_content,p.quality_standard,p.source_note,p.revision AS project_revision"+FROM+" AND q.id=?"+(lock?" FOR UPDATE":""),id);}
 Map<String,Object> source(long id,boolean lock){return source(id,lock,db.now());}
 Map<String,Object> source(long id,boolean lock,java.time.Instant observed){if(lock){var mapping=db.one("SELECT merchant_id,project_id FROM merchant_project WHERE id=?",id);db.one("SELECT id FROM merchant WHERE id=? FOR UPDATE",mapping.get("merchant_id"));db.one("SELECT id FROM standard_project WHERE id=? FOR UPDATE",mapping.get("project_id"));}var q=quote(id,lock);var versions=db.jdbc.queryForList("SELECT * FROM merchant_project_version WHERE merchant_project_id=? ORDER BY version DESC LIMIT 1"+(lock?" FOR UPDATE":""),id);var v=versions.isEmpty()?null:versions.get(0);boolean ready=v!=null&&number(v,"on_shelf")==1&&v.get("price") instanceof BigDecimal price&&price.signum()>0&&price.compareTo((BigDecimal)q.get("price"))==0&&v.get("actor_staff_id") instanceof Number actor&&actor.longValue()>0&&q.get("source_note") instanceof String note&&!note.isBlank()&&q.get("service_content") instanceof String content&&!content.isBlank()&&!instant(v.get("created_at")).isAfter(observed);
  List<Map<String,Object>> proofs=v==null?List.of():db.jdbc.queryForList("SELECT id,after_state FROM audit_log WHERE is_deleted=0 AND actor_type='staff_account' AND actor_id=? AND action='MERCHANT_PROJECT_SAVE' AND resource_type='merchant_project' AND resource_id=? AND JSON_EXTRACT(after_state,'$.version_id')=?",v.get("actor_staff_id"),id,v.get("id"));
  var latestAudit=db.jdbc.queryForList("SELECT id FROM audit_log WHERE actor_type='staff_account' AND action='MERCHANT_PROJECT_SAVE' AND resource_type='merchant_project' AND resource_id=? ORDER BY id DESC LIMIT 1",id);if(proofs.size()!=1||latestAudit.size()!=1||!Objects.equals(proofs.get(0).get("id"),latestAudit.get(0).get("id")))ready=false;else{var proof=db.parse(proofs.get(0).get("after_state"));ready=ready&&proof.path("merchant_project_id").asLong()==id&&proof.path("version").asLong()==number(v,"version")&&proof.path("status").asInt(-1)==1&&proof.path("price").isTextual()&&proof.get("price").asText().equals(((BigDecimal)q.get("price")).setScale(2).toPlainString());}
  var snapshot=new LinkedHashMap<String,Object>();snapshot.put("quote_id",id);snapshot.put("quote_version_id",v==null?null:v.get("id"));snapshot.put("quote_version",v==null?null:v.get("version"));snapshot.put("price",((BigDecimal)q.get("price")).setScale(2).toPlainString());snapshot.put("merchant",Map.of("id",q.get("merchant_id"),"name",q.get("merchant_name"),"region_code",Objects.toString(q.get("region_code"),"")));var project=new LinkedHashMap<String,Object>();for(String k:List.of("project_name","service_content","quality_standard","source_note"))project.put(k,Objects.toString(q.get(k),""));project.put("id",q.get("project_id"));project.put("revision",q.get("project_revision"));snapshot.put("project",project);
  var out=new LinkedHashMap<String,Object>();out.put("quote_id",id);out.put("state",ready?"READY":"UNKNOWN");out.put("source",snapshot);String hash=null;if(ready){var evidence=new LinkedHashMap<String,Object>();evidence.put("source",snapshot);evidence.put("quoted_at",iso(v.get("created_at")));evidence.put("actor",v.get("actor_staff_id"));evidence.put("audit_id",proofs.get(0).get("id"));hash=AuthTokens.sha256(db.json(AssessmentPolicyInput.canonical(db.mapper.valueToTree(evidence))));}out.put("source_hash",hash);return out;
 }
 private Map<String,Object> confirmed(JsonNode b){var s=source(b.path("quote_id").asLong(),true);if(!"READY".equals(s.get("state"))||!b.path("source_hash").asText().equals(s.get("source_hash"))||!CouponInput.time(b.get("valid_from")).isAfter(db.now()))throw conflict();return s;}
 Map<String,Object> row(long id,boolean lock){return db.one("SELECT * FROM price_monitor_policy WHERE id=?"+(lock?" FOR UPDATE":""),id);}
 Map<String,Object> view(Map<String,Object> r){var out=new LinkedHashMap<String,Object>();for(String k:List.of("id","quote_id","source_hash","price_unit","applicability_note","source_note","revision","status","rule_version"))out.put(k,r.get(k));for(String k:List.of("lower_price","upper_price"))out.put(k,((BigDecimal)r.get(k)).setScale(2).toPlainString());out.put("source_snapshot",db.parse(r.get("source_snapshot")));out.put("scope_confirmed",true);for(String k:List.of("valid_from","valid_to","created_at","published_at","stopped_at"))out.put(k,iso(r.get(k)));out.put("comparison_available",true);return out;}
 public Map<String,Object> quotes(OperatorActor a,int p){pageNumber(p);return db.reads.execute(tx->{auth(a,false);long total=db.jdbc.queryForObject("SELECT COUNT(*)"+FROM,Long.class);var rows=db.jdbc.queryForList("SELECT q.id"+FROM+" ORDER BY q.id DESC LIMIT 20 OFFSET ?",(p-1)*20L);return page(rows.stream().map(r->source(number(r,"id"),false)).toList(),total,p,20);});}
 public Map<String,Object> list(OperatorActor a,int p){pageNumber(p);return db.reads.execute(tx->{auth(a,false);long total=db.jdbc.queryForObject("SELECT COUNT(*) FROM price_monitor_policy",Long.class);return page(db.jdbc.queryForList("SELECT * FROM price_monitor_policy ORDER BY id DESC LIMIT 20 OFFSET ?",(p-1)*20L).stream().map(this::view).toList(),total,p,20);});}
 public Map<String,Object> detail(OperatorActor a,long id){com.autocare.platform.service.ServiceCatalog.validateId(id);return db.reads.execute(tx->{auth(a,false);return view(row(id,false));});}
 public JsonNode create(OperatorActor a,String key,JsonNode b){String normalized=WriteIntegrityService.normalizeKey(key),hash=AuthTokens.sha256(db.json(AssessmentPolicyInput.canonical(b)));return db.writes.execute(new Actor("operator_account",a.id()),"POST",PATH,key,b,()->auth(a,true),()->{
  var previous=db.jdbc.queryForList("SELECT id,submission_hash,creation_result FROM price_monitor_policy WHERE created_by=? AND submission_key=?",a.id(),normalized);if(!previous.isEmpty()){var r=previous.get(0);if(!hash.equals(r.get("submission_hash")))throw ReservationInput.bad();var saved=db.parse(r.get("creation_result"));if(!saved.isObject())throw new IllegalStateException("Price source receipt missing");Map<String,Object> value=db.mapper.convertValue(saved,new com.fasterxml.jackson.core.type.TypeReference<Map<String,Object>>(){});return new Change("PRICE_POLICY_CREATE","price_monitor_policy",number(r,"id"),Map.of(),Map.of(),value,false);}
  var s=confirmed(b);long id=db.insert("INSERT INTO price_monitor_policy(quote_id,source_hash,source_snapshot,lower_price,upper_price,price_unit,applicability_note,source_note,valid_from,valid_to,created_by,submission_key,submission_hash,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)",b.path("quote_id").asLong(),b.path("source_hash").asText(),db.json(s.get("source")),new BigDecimal(b.path("lower_price").asText()),new BigDecimal(b.path("upper_price").asText()),b.path("price_unit").asText(),b.path("applicability_note").asText(),b.path("source_note").asText(),time(CouponInput.time(b.get("valid_from"))),time(CouponInput.time(b.get("valid_to"))),a.id(),normalized,hash,time(db.now()));var after=view(row(id,true));db.jdbc.update("UPDATE price_monitor_policy SET creation_result=? WHERE id=?",db.json(after),id);return new Change("PRICE_POLICY_CREATE","price_monitor_policy",id,Map.of(),after,after);
 });}
 public JsonNode update(OperatorActor a,long id,String key,JsonNode b){com.autocare.platform.service.ServiceCatalog.validateId(id);return db.writes.execute(new Actor("operator_account",a.id()),"PUT",PATH+"/"+id,key,b,()->auth(a,true),()->{var s=confirmed(b);var r=row(id,true);if(!"DRAFT".equals(r.get("status"))||number(r,"revision")!=b.path("expected_revision").asLong())throw conflict();var before=view(r);db.jdbc.update("UPDATE price_monitor_policy SET quote_id=?,source_hash=?,source_snapshot=?,lower_price=?,upper_price=?,price_unit=?,applicability_note=?,source_note=?,valid_from=?,valid_to=?,revision=revision+1 WHERE id=?",b.path("quote_id").asLong(),b.path("source_hash").asText(),db.json(s.get("source")),new BigDecimal(b.path("lower_price").asText()),new BigDecimal(b.path("upper_price").asText()),b.path("price_unit").asText(),b.path("applicability_note").asText(),b.path("source_note").asText(),time(CouponInput.time(b.get("valid_from"))),time(CouponInput.time(b.get("valid_to"))),id);var after=view(row(id,true));return new Change("PRICE_POLICY_UPDATE","price_monitor_policy",id,before,after,after);});}
 public JsonNode status(OperatorActor a,long id,String key,JsonNode b){com.autocare.platform.service.ServiceCatalog.validateId(id);return db.writes.execute(new Actor("operator_account",a.id()),"PUT",PATH+"/"+id+"/status",key,b,()->auth(a,true),()->{String target=b.path("status").asText();var first=row(id,false);if(target.equals("PUBLISHED")){var source=source(number(first,"quote_id"),true);if(!"READY".equals(source.get("state"))||!Objects.equals(source.get("source_hash"),first.get("source_hash"))||!instant(first.get("valid_from")).isAfter(db.now()))throw conflict();}var r=row(id,true);if(number(r,"revision")!=b.path("expected_revision").asLong()||!(target.equals("PUBLISHED")?"DRAFT".equals(r.get("status")):target.equals("STOPPED")&&"PUBLISHED".equals(r.get("status")))||!Objects.equals(first.get("source_hash"),r.get("source_hash")))throw conflict();var before=view(r);try{db.jdbc.update("UPDATE price_monitor_policy SET status=?,revision=revision+1,published_at=?,stopped_at=? WHERE id=?",target,target.equals("PUBLISHED")?time(db.now()):r.get("published_at"),target.equals("STOPPED")?time(db.now()):null,id);}catch(org.springframework.dao.DuplicateKeyException e){throw conflict();}var after=view(row(id,true));return new Change("PRICE_POLICY_STATUS","price_monitor_policy",id,before,after,after);});}
}
